cd /Users/dev/workspace/vivarium/experiments/tier3/results/workspace && python3 - <<'EOF'
import json, glob, math

total = 0
kinds = {}
units = {}
for path in sorted(glob.glob('data/*.jsonl')):
    with open(path) as f:
        for line in f:
            rec = json.loads(line)
            kinds[rec.get('kind')] = kinds.get(rec.get('kind'), 0) + 1
            if rec.get('kind') != 'span':
                continue
            el = rec.get('body', {}).get('span', {}).get('elapsed')
            if el is None:
                continue
            v, u = el['value'], el['unit']
            units[u] = units.get(u, 0) + 1
            if u == 'ms':
                total += v
            elif u == 'us':
                total += v // 1000
            elif u == 's':
                total += v * 1000
            else:
                print("UNKNOWN UNIT", u)
print("total:", total)
print("kinds:", kinds)
print("units:", units)
EOF
